package analyze

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// editsFixture builds a small project with one of everything the
// assembly planners work on: string and numeric switches, a
// two-switch function, a mode switch whose cases lean on a sibling
// file's import, a struct with keyed and positional literals, map
// and slice tables, an ambiguous struct and function name, and a
// generated file that must be refused.
func editsFixture(t *testing.T) (string, *Project) {
	t.Helper()
	dir := t.TempDir()
	write := func(rel, src string) {
		full := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("go.mod", "module example.com/edits\n\ngo 1.21\n")
	write("other/other.go", `package other

const (
	ModeFast = 1
	ModeSlow = 2
)
`)
	write("shop/defs.go", `package shop

import other "example.com/edits/other"

const ModeDefault = other.ModeFast
`)
	write("shop/switches.go", `package shop

func Describe(kind string) string {
	switch kind {
	case "apple":
		return "a fruit"
	case "carrot":
		return "a vegetable"
	default:
		return "something else"
	}
}

func Price(code int) int {
	switch code {
	case 1:
		return 100
	case 2:
		return 200
	default:
		return 0
	}
}

func Route(mode string, level int) string {
	switch mode {
	case "fast":
		return "fast lane"
	default:
		return "slow lane"
	}
	switch {
	case level > 10:
		return "high"
	default:
		return "low"
	}
}

func ModeName(mode int) string {
	switch mode {
	case ModeDefault:
		return "the default mode"
	default:
		return "some other mode"
	}
}

func Plain() string {
	return "no switch here"
}
`)
	write("shop/types.go", `package shop

type Config struct {
	Host  string
	Port  int
	Debug bool
}

func Keyed() Config {
	return Config{Host: "example.com", Port: 443}
}
`)
	write("shop/defaults.go", `package shop

var DefaultConfig = Config{"localhost", 8080, false}
`)
	write("shop/tables.go", `package shop

var Greetings = map[string]string{
	"hello": "Hello",
	"bye":   "Bye",
}

var Ports = []int{80, 443}

var EmptyTable = map[string]string{}
`)
	write("shop/funcs.go", `package shop

// Greet says hello to someone.
func Greet(name string) string {
	return "Hello, " + name
}

func Load() int {
	return 1
}
`)
	write("shop/gen.go", `// Code generated by a tool. DO NOT EDIT.

package shop

func GeneratedPick(kind string) string {
	switch kind {
	case "a":
		return "A"
	default:
		return "?"
	}
}

type GeneratedThing struct {
	Name string
}
`)
	write("helper/helper.go", `package helper

type State struct {
	On bool
}

func Load() int {
	return 2
}
`)
	write("helper2/helper2.go", `package helper2

type State struct {
	Ready bool
}
`)
	p, err := Analyze(dir)
	if err != nil {
		t.Fatalf("analyze fixture: %v", err)
	}
	return dir, p
}

// applyPlan writes a plan's After bytes the way the chat does.
func applyPlan(t *testing.T, dir string, plan *EditPlan) {
	t.Helper()
	for _, f := range plan.Files {
		if err := os.WriteFile(filepath.Join(dir, f.Rel), f.After, 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

// buildFixture runs go build in the fixture root.
func buildFixture(t *testing.T, dir string) {
	t.Helper()
	goBin, err := exec.LookPath("go")
	if err != nil {
		t.Skip("go toolchain not on PATH")
	}
	cmd := exec.Command(goBin, "build", "./...")
	cmd.Dir = dir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("fixture build after edit: %v\n%s", err, out)
	}
}

func mustPlan(t *testing.T, p *Project, req EditRequest) *EditPlan {
	t.Helper()
	plan, refusal := p.PlanEdit(req)
	if refusal != "" {
		t.Fatalf("PlanEdit(%+v) refused: %s", req, refusal)
	}
	if plan == nil {
		t.Fatalf("PlanEdit(%+v) returned no plan and no refusal", req)
	}
	return plan
}

func mustRefuse(t *testing.T, p *Project, req EditRequest, want string) string {
	t.Helper()
	plan, refusal := p.PlanEdit(req)
	if plan != nil {
		t.Fatalf("PlanEdit(%+v) planned, want refusal containing %q; plan: %s", req, want, plan.Summary)
	}
	if !strings.Contains(refusal, want) {
		t.Fatalf("PlanEdit(%+v) refusal %q, want substring %q", req, refusal, want)
	}
	return refusal
}

// reanalyze re-reads the fixture after applying a plan.
func reanalyze(t *testing.T, dir string) *Project {
	t.Helper()
	p, err := Analyze(dir)
	if err != nil {
		t.Fatalf("re-analyze: %v", err)
	}
	return p
}

// --- add_case ---

func TestPlanAddCaseStringSwitch(t *testing.T) {
	dir, p := editsFixture(t)
	plan := mustPlan(t, p, EditRequest{Kind: EditAddCase, FuncName: "Describe", CaseExpr: "plum"})
	if !strings.Contains(plan.Diff(), `+	case "plum":`) {
		t.Fatalf("diff missing the new case:\n%s", plan.Diff())
	}
	if !strings.Contains(plan.Diff(), `+		return "a vegetable"`) && !strings.Contains(string(plan.Files[0].After), `case "plum":`) {
		t.Fatalf("new case body not cloned from sibling:\n%s", plan.Files[0].After)
	}
	applyPlan(t, dir, plan)
	buildFixture(t, dir)
	if !plan.Verify(reanalyze(t, dir)) {
		t.Fatal("verify: the plum case should exist after applying")
	}
}

func TestPlanAddCasePicksNamedSwitch(t *testing.T) {
	_, p := editsFixture(t)
	// Route has two switches; unnamed is an honest refusal.
	mustRefuse(t, p, EditRequest{Kind: EditAddCase, FuncName: "Route", CaseExpr: "medium"},
		"has 2 switches")
	// Naming the subject picks the right one.
	plan := mustPlan(t, p, EditRequest{Kind: EditAddCase, FuncName: "Route", CaseExpr: "medium", SwitchOn: "mode"})
	if !strings.Contains(string(plan.Files[0].After), `case "medium":`) {
		t.Fatalf("named-switch plan missing the case:\n%s", plan.Files[0].After)
	}
}

