func TestPlanAddCaseImportCopiedFromSibling(t *testing.T) {
	dir, p := editsFixture(t)
	plan := mustPlan(t, p, EditRequest{Kind: EditAddCase, FuncName: "ModeName", CaseExpr: "other.ModeSlow"})
	after := string(plan.Files[0].After)
	if !strings.Contains(after, `other "example.com/edits/other"`) {
		t.Fatalf("import not copied into the switch's file:\n%s", after)
	}
	if !strings.Contains(after, "case other.ModeSlow:") {
		t.Fatalf("new case missing:\n%s", after)
	}
	applyPlan(t, dir, plan)
	buildFixture(t, dir)
	if !plan.Verify(reanalyze(t, dir)) {
		t.Fatal("verify: other.ModeSlow case should exist")
	}
}

// --- add_field ---

func TestPlanAddFieldPositionalAndKeyed(t *testing.T) {
	dir, p := editsFixture(t)
	plan := mustPlan(t, p, EditRequest{Kind: EditAddField, StructName: "Config", FieldName: "Timeout", FieldType: "int"})
	if len(plan.Files) != 2 {
		t.Fatalf("want struct file + positional literal file, got %d files", len(plan.Files))
	}
	var joined string
	for _, f := range plan.Files {
		joined += string(f.After)
	}
	if !strings.Contains(joined, "Timeout int") {
		t.Fatalf("field line missing:\n%s", joined)
	}
	if !strings.Contains(joined, `Config{"localhost", 8080, false, 0}`) {
		t.Fatalf("positional literal not extended with the zero value:\n%s", joined)
	}
	applyPlan(t, dir, plan)
	buildFixture(t, dir)
	if !plan.Verify(reanalyze(t, dir)) {
		t.Fatal("verify: Config.Timeout should exist")
	}
}

func TestPlanAddFieldAfterAnchor(t *testing.T) {
	dir, p := editsFixture(t)
	plan := mustPlan(t, p, EditRequest{Kind: EditAddField, StructName: "Config", FieldName: "Name", FieldType: "string", AfterField: "Host"})
	var typesAfter string
	for _, f := range plan.Files {
		if strings.HasSuffix(f.Rel, "types.go") {
			typesAfter = string(f.After)
		}
		if strings.Contains(string(f.After), "DefaultConfig") {
			if !strings.Contains(string(f.After), `Config{"localhost", "", 8080, false}`) {
				t.Fatalf("zero value landed in the wrong slot:\n%s", f.After)
			}
		}
	}
	host := strings.Index(typesAfter, "\tHost")
	name := strings.Index(typesAfter, "\tName")
	port := strings.Index(typesAfter, "\tPort")
	if !(host >= 0 && name > host && port > name) {
		t.Fatalf("field not placed after Host:\n%s", typesAfter)
	}
	applyPlan(t, dir, plan)
	buildFixture(t, dir)
	if !plan.Verify(reanalyze(t, dir)) {
		t.Fatal("verify: Config.Name should exist")
	}
}

