func TestPlanRegisterMap(t *testing.T) {
	dir, p := editsFixture(t)
	plan := mustPlan(t, p, EditRequest{Kind: EditRegister, TableName: "Greetings", Key: "thanks"})
	if !strings.Contains(string(plan.Files[0].After), `"thanks": "Thanks"`) {
		t.Fatalf("entry not assembled from the sibling (want the Title-cased echo value):\n%s", plan.Files[0].After)
	}
	applyPlan(t, dir, plan)
	buildFixture(t, dir)
	if !plan.Verify(reanalyze(t, dir)) {
		t.Fatal("verify: Greetings[thanks] should exist")
	}
}

