// --- add_func ---

func TestPlanCloneFunc(t *testing.T) {
	dir, p := editsFixture(t)
	plan := mustPlan(t, p, EditRequest{Kind: EditAddFunc, SiblingName: "Greet", NewName: "GreetLoudly"})
	after := string(plan.Files[0].After)
	if !strings.Contains(after, "func GreetLoudly(name string) string {") {
		t.Fatalf("cloned function missing or misnamed:\n%s", after)
	}
	if !strings.Contains(after, "// GreetLoudly says hello to someone.") {
		t.Fatalf("doc comment not carried over with the new name:\n%s", after)
	}
	applyPlan(t, dir, plan)
	buildFixture(t, dir)
	if !plan.Verify(reanalyze(t, dir)) {
		t.Fatal("verify: GreetLoudly should exist")
	}
}

func TestPlanCloneFuncNameTakenRefused(t *testing.T) {
	_, p := editsFixture(t)
	mustRefuse(t, p, EditRequest{Kind: EditAddFunc, SiblingName: "Greet", NewName: "Load"},
		"already exists")
}

func TestPlanAmbiguousFuncRefused(t *testing.T) {
	_, p := editsFixture(t)
	refusal := mustRefuse(t, p, EditRequest{Kind: EditAddFunc, SiblingName: "Load", NewName: "Load2"},
		"more than one function")
	for _, want := range []string{"shop", "helper"} {
		if !strings.Contains(refusal, want) {
			t.Fatalf("ambiguity refusal should mention %s:\n%s", want, refusal)
		}
	}
	// Qualifying by package resolves it.
	mustPlan(t, p, EditRequest{Kind: EditAddFunc, SiblingName: "helper.Load", NewName: "Load2"})
}

// --- diff ---

func TestUnifiedDiffShape(t *testing.T) {
	d := unifiedDiff("x.go", []byte("a\nb\nc\n"), []byte("a\nB\nc\n"))
	for _, want := range []string{"--- a/x.go", "+++ b/x.go", "@@", "-b", "+B", " a", " c"} {
		if !strings.Contains(d, want) {
			t.Fatalf("diff missing %q:\n%s", want, d)
		}
	}
	if d := unifiedDiff("x.go", []byte("a\n"), []byte("a\n")); d != "" {
		t.Fatalf("identical texts should diff empty, got %q", d)
	}
}
